package main

import (
	"fmt"
	"sync"
)

type Service struct{ ID int }

var (
	once     sync.Once
	instance *Service
)

func GetService() *Service {
	once.Do(func() { // runs exactly once across all goroutines
		instance = &Service{ID: 1}
		fmt.Println("initialized service")
	})
	return instance // every caller sees the fully built instance
}

func main() {
	var wg sync.WaitGroup
	for i := 0; i < 5; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_ = GetService() // concurrent first calls
		}()
	}
	wg.Wait()
	fmt.Println("service id:", GetService().ID)
}

package main

import (
	"fmt"
	"sort"
	"sync"
)

var cache sync.Map // key: int, value: int (squared)

func square(n int) int {
	if v, ok := cache.Load(n); ok { // lock-free read fast path
		return v.(int) // values are interface{}, so assert the type
	}
	computed := n * n
	// LoadOrStore avoids a race if two goroutines compute the same key.
	actual, _ := cache.LoadOrStore(n, computed)
	return actual.(int)
}

func main() {
	var wg sync.WaitGroup
	for i := 1; i <= 4; i++ {
		wg.Add(1)
		go func(n int) {
			defer wg.Done()
			_ = square(n)
		}(i)
	}
	wg.Wait()

	var keys []int
	cache.Range(func(k, v any) bool { // iterate all entries
		keys = append(keys, k.(int))
		return true // return false to stop early
	})
	sort.Ints(keys) // Range order is unspecified; sort for stable output
	for _, k := range keys {
		v, _ := cache.Load(k)
		fmt.Printf("%d -> %d\n", k, v.(int))
	}
}
